void Backup(string path){if(string.IsNullOrEmpty(path))return;string to=stage+"/BeforeFiles/"+path;System.IO.Directory.CreateDirectory(System.IO.Path.GetDirectoryName(to));if(!System.IO.File.Exists(to))System.IO.File.Copy(path,to);}
