var weather=UnityEditor.AssetDatabase.LoadAssetAtPath<WeatherData>("Assets/Resources/Data/WeatherData.asset");Backup(UnityEditor.AssetDatabase.GetAssetPath(weather));weather.dayLightColor=new Color(1,.90f,.79f);weather.dayIntensity=.8f;weather.dayAmbientColor=new Color(.34f,.35f,.37f);UnityEditor.EditorUtility.SetDirty(weather);
