void Packed(Material m,Texture map){if(map==null)throw new System.Exception("Missing packed mask: "+m.name);m.SetTexture("_MetallicGlossMap",map);m.SetFloat("_UsePackedMask",1);m.EnableKeyword("_GAMELIT_PACKED_MASK");m.SetFloat("_Metallic",1);m.SetFloat("_Smoothness",1);m.DisableKeyword("_METALLICSPECGLOSSMAP");UnityEditor.EditorUtility.SetDirty(m);UnityEditor.AssetDatabase.SaveAssetIfDirty(m);}
