 string path="Assets/ChibiSurvivor/NPC/StoryNPC62/Materials/"+name+".mat";Backup(path);var m=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(path);var mask=UnityEditor.AssetDatabase.LoadAssetAtPath<Texture>("Assets/ChibiSurvivor/NPC/StoryNPC62/Textures/"+name+"/"+name+"_Mask.png");Packed(m,mask);m.SetFloat("_GrimeStrength",.12f);m.SetColor("_GrimeColor",new Color(.65f,.62f,.59f));m.SetFloat("_ShadowDesaturation",.2f);m.SetFloat("_RimStrength",.045f);UnityEditor.EditorUtility.SetDirty(m);materialRows.Add(new{path,mask=mask.name});
