Material Variant(string name,string source,Vector2 tiling,Color? tint=null){string path=folder+"/"+name+".mat";var m=UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){m=new Material(UnityEditor.AssetDatabase.LoadAssetAtPath<Material>(root+"/Materials/"+source+".mat")){name=name};UnityEditor.AssetDatabase.CreateAsset(m,path);}m.shader=shader;m.SetTextureScale("_BaseMap",tiling);if(tint.HasValue)m.SetColor("_BaseColor",tint.Value);m.SetFloat("_BumpScale",.22f);m.SetFloat("_GrimeStrength",.14f);m.SetFloat("_GrimeScale",3);m.SetFloat("_ShadowDesaturation",.25f);m.SetFloat("_RimStrength",0);m.EnableKeyword("_SPECULARHIGHLIGHTS_OFF");m.EnableKeyword("_ENVIRONMENTREFLECTIONS_OFF");var map=m.GetTexture("_MetallicGlossMap");if(map!=null)Packed(m,map);UnityEditor.EditorUtility.SetDirty(m);materialRows.Add(new{path,tiling=tiling.ToString()});return m;}
